describe('Race Condition Handling in Search', () => {
    beforeEach(() => {
        cy.visit('/search'); // Replace with the actual search page URL
    });

    it('should display the latest search result when multiple requests are made', () => {
        cy.intercept('GET', '/api/search*', (req) => {
            req.reply((res) => {
                res.send({ results: ['Result 1', 'Result 2', 'Result 3'] });
            });
        }).as('searchRequest');

        cy.get('input[name="search"]').type('test{enter}');
        cy.wait('@searchRequest');

        cy.intercept('GET', '/api/search*', (req) => {
            req.reply((res) => {
                res.send({ results: ['Latest Result'] });
            });
        }).as('latestSearchRequest');

        cy.get('input[name="search"]').type('test again{enter}');
        cy.wait('@latestSearchRequest');

        cy.get('.search-results').should('contain', 'Latest Result');
    });

    it('should not display outdated results when a new search is initiated', () => {
        cy.intercept('GET', '/api/search*', (req) => {
            req.reply((res) => {
                res.send({ results: ['Outdated Result'] });
            });
        }).as('outdatedSearchRequest');

        cy.get('input[name="search"]').type('old search{enter}');
        cy.wait('@outdatedSearchRequest');

        cy.intercept('GET', '/api/search*', (req) => {
            req.reply((res) => {
                res.send({ results: ['New Search Result'] });
            });
        }).as('newSearchRequest');

        cy.get('input[name="search"]').type('new search{enter}');
        cy.wait('@newSearchRequest');

        cy.get('.search-results').should('not.contain', 'Outdated Result');
        cy.get('.search-results').should('contain', 'New Search Result');
    });
});
